// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address to, uint256 value) public {
        vm.assume(to != address(0));
        vm.assume(value <= 10_000_000_000_000_000_000);
        (bool success, bytes memory data) = address(c).call(abi.encodeCall(c.transfer, (to, value)));
        if (success) {
            bool ret = abi.decode(data, (bool));
            assertTrue(ret);
        }
    }
}

